mapper.select:
select n.id, n.receiver_user_id, n.actor_user_id,
       actor.nickname as actor_nickname, actor.avatar_url as actor_avatar_url,
       n.type, n.content_id, n.comment_id, n.message, n.read_at, n.created_at
from notifications n
left join users actor on actor.id = n.actor_user_id
where n.receiver_user_id = #{userId}

    and (
        n.created_at < #{cursorCreatedAt}
        or (n.created_at = #{cursorCreatedAt} and n.id < #{cursorId})
    )

order by n.created_at desc, n.id desc
limit #{limit}

select unread_count
from notification_unread_stats
where user_id = #{userId}

mapper.update:
update notifications
set read_at = #{readAt}, updated_at = current_timestamp
where id = #{notificationId}
  and receiver_user_id = #{userId}
  and read_at is null

update notification_unread_stats
set unread_count = case
        when unread_count > #{delta} then unread_count - #{delta}
        else 0
    end,
    updated_at = current_timestamp
where user_id = #{userId}
